function validate([n, cost]) {
  if (n < 2 || n > 100000 || n % 2 !== 0) return 'n is an even number from 2 to 10^5.';
  if (cost.length !== n) return 'cost needs exactly n rows, one per house.';
  if (cost.some(row => row.length !== 3)) return 'Each row of cost has exactly 3 prices.';
  if (cost.some(row => row.some(v => v < 0 || v > 100000))) return 'Each price is between 0 and 10^5.';
  return null;
}

