function minCost(n, cost) {
  const half = n / 2;
  const grid = () => Array.from({ length: 3 }, () => new Array(3).fill(Infinity));
  // dp[a][b]: cheapest cost of the pairs so far when the newest pair uses colours a (left) and b (right).
  let dp = grid();
  for (let a = 0; a < 3; a++) {
    for (let b = 0; b < 3; b++) {
      if (a !== b) dp[a][b] = cost[0][a] + cost[n - 1][b];
    }
  }

  for (let i = 1; i < half; i++) {
    const mirror = n - 1 - i;
    const next = grid();
    for (let a = 0; a < 3; a++) {
      for (let b = 0; b < 3; b++) {
        if (a === b) continue;
        let cheapest = Infinity;
        for (let prevA = 0; prevA < 3; prevA++) {
          for (let prevB = 0; prevB < 3; prevB++) {
            if (prevA !== a && prevB !== b) cheapest = Math.min(cheapest, dp[prevA][prevB]);
          }
        }
        next[a][b] = cheapest + cost[i][a] + cost[mirror][b];
      }
    }
    dp = next;
  }
  return Math.min(...dp.flat());
}

