function minCost(n, cost) {
  // Try every colouring house by house, skipping colours that break a rule with an earlier house.
  const colours = new Array(n);
  let best = Infinity;
  const paint = (house, spent) => {
    if (house === n) {
      best = Math.min(best, spent);
      return;
    }
    for (let c = 0; c < 3; c++) {
      if (house > 0 && colours[house - 1] === c) continue;
      if (house >= n / 2 && colours[n - 1 - house] === c) continue;
      colours[house] = c;
      paint(house + 1, spent + cost[house][c]);
    }
  };
  paint(0, 0);
  return best;
}

