function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 * (1 + Math.floor(rand() * 5));
  const top = size === 'large' ? [10, 100000][Math.floor(rand() * 2)] : [0, 3, 20, 100000][Math.floor(rand() * 4)];
  const cost = Array.from({ length: n }, () => Array.from({ length: 3 }, () => Math.floor(rand() * (top + 1))));
  return [n, cost];
}
